// ---------------------------------------------------------------------------
// Figure aspect ratios — the four canonical shapes
// Every BlockFigure on a case-study page picks one of these so cells line up.
// ---------------------------------------------------------------------------

export const FIGURE_RATIOS = {
  /** 3 : 1 — wide banner, full-width hero strip */
  banner: "aspect-[3/1]",
  /** 16 : 9 — video / cinematic */
  video: "aspect-video",
  /** 4 : 3 — classic media; the default for paired cells */
  classic: "aspect-[4/3]",
  /** 1 : 1 — square; for triptychs and dense grids */
  square: "aspect-square",
};

/** Resolve a ratio key (or raw class) to a Tailwind aspect class. */
export function figureRatioClass(ratio = "classic") {
  return FIGURE_RATIOS[ratio] || ratio;
}

