export function BlockText({ heading, paragraphs = [], className = "" }) {
  return (
    <div className={className}>
      {heading && <p className={`${blockMonoLabelClass} mb-2`}>{heading}</p>}
      {paragraphs.map((p, i) => (
        <p key={i} className={`${blockBodyClass} mb-3 last:mb-0`}>
          {p}
        </p>
      ))}
    </div>
  );
}

