/**
 * Real image figure, pinned to one of the four canonical aspect ratios so
 * every cell in a row lines up. Use this instead of a raw <img> on case-study
 * pages.
 *
 * Props:
 *   src       — image URL
 *   alt       — alt text (required)
 *   ratio     — "banner" (3:1) | "video" (16:9) | "classic" (4:3, default) | "square" (1:1)
 *   fit       — "cover" (default) | "contain"
 *   invert    — bool; apply dark:invert for diagrams/tables on dark backgrounds
 *   caption   — optional small caption shown below the image
 *   className — extra classes on the outer figure
 */
export function BlockFigure({
  src,
  alt,
  ratio = "classic",
  fit = "cover",
  invert = false,
  caption,
  className = "",
}) {
  const ratioCls = figureRatioClass(ratio);
  const fitCls = fit === "contain" ? "object-contain" : "object-cover";
  const bgCls = fit === "contain" ? "bg-neutral-50 dark:bg-neutral-950" : "bg-neutral-100 dark:bg-neutral-900";
  const invertCls = invert ? "dark:invert" : "";
  return (
    <figure className={`flex flex-col w-full h-full ${className}`}>
      <div className={`relative w-full ${ratioCls} overflow-hidden ${bgCls}`}>
        <img
          src={src}
          alt={alt}
          loading="lazy"
          className={`absolute inset-0 w-full h-full ${fitCls} ${invertCls}`}
        />
      </div>
      {caption ? (
        <figcaption className={`${blockTechnicalLabelClass} px-3 py-2 border-t border-border dark:border-neutral-800 bg-surface-muted dark:bg-neutral-950`}>
          <span aria-hidden className="mr-1.5 text-content-subtle dark:text-neutral-600">▸</span>
          {caption}
        </figcaption>
      ) : null}
    </figure>
  );
}

/** Placeholder media cell — aspect ratio via Tailwind arbitrary value */
export function BlockMediaPlaceholder({
  label,
  variant = "light",
  spanLabel,
  aspectClass = "aspect-video",
  className = "",
}) {
  const bg =
    variant === "dark"
      ? "bg-neutral-300 dark:bg-neutral-700"
      : variant === "darker"
      ? "bg-neutral-400 dark:bg-neutral-600"
      : "bg-neutral-200 dark:bg-neutral-800";

  return (
    <div
      className={`relative border border-border dark:border-neutral-700 flex flex-col items-center justify-center ${bg} ${aspectClass} ${className}`}
      style={{
        backgroundImage:
          "repeating-linear-gradient(45deg, rgba(10,10,10,.06) 0 1px, transparent 1px 8px)",
      }}
    >
      {spanLabel && (
        <span className="absolute right-2 top-2 font-mono text-meta tracking-[0.04em] px-1 py-0.5 border border-content-subtle dark:border-neutral-500 bg-white/90 dark:bg-black/50">
          {spanLabel}
        </span>
      )}
      <span className="font-mono text-meta uppercase text-content-secondary dark:text-neutral-300 text-center px-4">
        {label}
      </span>
    </div>
  );
}

