// --- Portrait corner tick -------------------------------------------------
// Small registration-style square poking out of the top-left corner of the
// portrait. Tune these three numbers to taste:
//   TICK_SIZE_PX   — edge length of the square (try 6–10).
//   TICK_OFFSET_PX — how far the square sits relative to the portrait corner.
//                    Negative values pull it OUTWARD (it pokes past the edge);
//                    positive values inset it INSIDE the portrait.
//                    e.g. -4 = pokes out by 4px,  6 = inset 6px from corner.
//   TICK_VISIBLE   — set to false to hide it entirely.
const TICK_SIZE_PX =24;
const TICK_OFFSET_PX = -4;
const TICK_VISIBLE = false;

const AboutPage = () => {
  return (
    <main
      className="
        flex flex-1 flex-col min-h-0 w-full
        bg-white dark:bg-black
        pt-[72px] box-border
        transition-colors duration-500
      "
    >
      {/* Vertical centering wrapper. min-h-full + flex items-center keeps the
          row centred when content fits, falls back to scroll if it doesn't. */}
      <div className="flex-1 min-h-0 overflow-y-auto overscroll-y-contain">
        <div className="min-h-full flex items-center">
          <div
            className="
              w-full max-w-[1440px] mx-auto
              px-6 lg:px-12
              py-8 lg:py-10
            "
          >
            <div
              className="
                flex flex-col lg:flex-row
                items-start
                gap-8 lg:gap-14
              "
            >
              <Portrait />
              <Content />
            </div>
          </div>
        </div>
      </div>
    </main>
  );
};

/** 280px square portrait + small corner registration mark. */
const Portrait = () => (
  <aside className="shrink-0 mx-auto lg:mx-0">
    {/* Outer wrapper is `relative` (not the image box) so the tick can sit
        OUTSIDE the portrait without being clipped by overflow-hidden. */}
    <div className="relative inline-block">
      {TICK_VISIBLE && (
        <span
          aria-hidden="true"
          className="absolute z-[1] bg-black dark:bg-white"
          style={{
            top: `${TICK_OFFSET_PX}px`,
            left: `${TICK_OFFSET_PX}px`,
            width: `${TICK_SIZE_PX}px`,
            height: `${TICK_SIZE_PX}px`,
          }}
        />
      )}
      <div
        className="
          relative
          w-[200px] h-[200px] sm:w-[240px] sm:h-[240px] lg:w-[280px] lg:h-[280px]
          overflow-hidden
          bg-neutral-100 dark:bg-neutral-900
        "
      >
        <img
          src="/General/Profile Picture 2024_Square.jpg"
          alt="Portrait of Shareef Jasim"
          className="absolute inset-0 h-full w-full object-cover"
        />
      </div>
    </div>
  </aside>
);

